from pathlib import Path

path = Path('index.html')
text = path.read_text(encoding='utf-8')

# 1. Add Export GIF beside Export WebM in the main toolbar.
old = '''      <button class="btn small primary" id="btn-export-webm-top" style="flex:0 0 auto;" title="Export the current animation as a WebM file">Export WebM</button>'''
new = old + '''\n      <button class="btn small primary" id="btn-export-gif-top" style="flex:0 0 auto;" title="Export the current animation as an animated GIF">Export GIF</button>'''
if 'id="btn-export-gif-top"' not in text:
    if old not in text:
        raise SystemExit('Top Export WebM button anchor not found')
    text = text.replace(old, new, 1)

# 2. Add Export GIF beside the existing recorder export button.
old = '''      <button class="btn primary" id="btn-record">Export WebM</button>\n      <button class="btn danger" id="btn-stop" disabled>Stop</button>'''
new = '''      <button class="btn primary" id="btn-record">Export WebM</button>\n      <button class="btn primary" id="btn-export-gif">Export GIF</button>\n      <button class="btn danger" id="btn-stop" disabled>Stop</button>'''
if 'id="btn-export-gif"' not in text:
    if old not in text:
        raise SystemExit('Recorder Export WebM button anchor not found')
    text = text.replace(old, new, 1)

# 3. Bind the new buttons with the existing export controls.
old = '''  const btnRecord = document.getElementById('btn-record');\n  const btnExportWebMTop = document.getElementById('btn-export-webm-top');\n  const btnStop = document.getElementById('btn-stop');'''
new = '''  const btnRecord = document.getElementById('btn-record');\n  const btnExportWebMTop = document.getElementById('btn-export-webm-top');\n  const btnExportGIF = document.getElementById('btn-export-gif');\n  const btnExportGIFTop = document.getElementById('btn-export-gif-top');\n  const btnStop = document.getElementById('btn-stop');'''
if "const btnExportGIF = document.getElementById('btn-export-gif');" not in text:
    if old not in text:
        raise SystemExit('Export control declaration anchor not found')
    text = text.replace(old, new, 1)

# 4. Add deterministic GIF export using Luke Animate's existing render clock.
anchor = '''  if(btnExportWebMTop){\n    btnExportWebMTop.addEventListener('click', ()=>{\n      if(btnRecord && !btnRecord.disabled) btnRecord.click();\n    });\n  }\n\n  btnRecord.addEventListener('click', ()=>{'''

insert = '''  if(btnExportWebMTop){\n    btnExportWebMTop.addEventListener('click', ()=>{\n      if(btnRecord && !btnRecord.disabled) btnRecord.click();\n    });\n  }\n\n  let gifExportActive = false;\n  let gifEncoderModulePromise = null;\n\n  function loadGifEncoderModule(){\n    if(!gifEncoderModulePromise){\n      gifEncoderModulePromise = import('https://unpkg.com/gifenc@1.0.3?module');\n    }\n    return gifEncoderModulePromise;\n  }\n\n  function waitAnimationFrames(count=2){\n    return new Promise(resolve=>{\n      const step=()=>{\n        count-=1;\n        if(count<=0) resolve();\n        else requestAnimationFrame(step);\n      };\n      requestAnimationFrame(step);\n    });\n  }\n\n  async function exportAnimatedGIF(){\n    if(gifExportActive) return;\n    if(mediaRecorder && mediaRecorder.state === 'recording'){\n      alert('Stop the WebM export before exporting a GIF.');\n      return;\n    }\n\n    const fps = Math.max(1, getTimelineFPS());\n    const duration = Math.max(0.001, timelineDuration);\n    const totalFrames = Math.max(1, Math.round(duration * fps));\n    const frameDelay = Math.max(10, Math.round(1000 / fps));\n    const restorePlaying = playing;\n    const restoreTime = t;\n    const restoreExportState = {\n      active: exportPlayback.active,\n      fps: exportPlayback.fps,\n      duration: exportPlayback.duration,\n      totalFrames: exportPlayback.totalFrames,\n      currentFrameIndex: exportPlayback.currentFrameIndex,\n      recorderStarted: exportPlayback.recorderStarted\n    };\n\n    gifExportActive = true;\n    if(btnExportGIF) btnExportGIF.disabled = true;\n    if(btnExportGIFTop) btnExportGIFTop.disabled = true;\n    if(btnRecord) btnRecord.disabled = true;\n    if(btnExportWebMTop) btnExportWebMTop.disabled = true;\n    if(btnStop) btnStop.disabled = true;\n    if(btnExportGIFTop) btnExportGIFTop.textContent = 'Loading GIF…';\n    if(btnExportGIF) btnExportGIF.textContent = 'Loading GIF…';\n\n    let cleanViewStarted = false;\n\n    try{\n      const { GIFEncoder, quantize, applyPalette } = await loadGifEncoderModule();\n      const gif = GIFEncoder();\n      const frameCanvas = document.createElement('canvas');\n      frameCanvas.width = W;\n      frameCanvas.height = H;\n      const frameContext = frameCanvas.getContext('2d', {alpha:true, willReadFrequently:true});\n\n      beginCleanWebMExportView();\n      cleanViewStarted = true;\n      exportPlayback.active = true;\n      exportPlayback.fps = fps;\n      exportPlayback.duration = duration;\n      exportPlayback.totalFrames = totalFrames;\n      exportPlayback.recorderStarted = false;\n      playing = false;\n      layers.forEach(layer => layer.state = {});\n\n      for(let frameIndex=0; frameIndex<totalFrames; frameIndex+=1){\n        exportPlayback.currentFrameIndex = frameIndex;\n        t = frameIndex / fps;\n        syncActiveSceneFrameForTime(t, true);\n\n        // The normal Luke Animate render loop uses exportPlayback.currentFrameIndex.\n        // Wait for it to paint this exact frame before reading the stage canvas.\n        await waitAnimationFrames(2);\n\n        frameContext.clearRect(0,0,W,H);\n        frameContext.drawImage(canvas,0,0,W,H);\n        const image = frameContext.getImageData(0,0,W,H);\n        const palette = quantize(image.data, 256, {\n          format:'rgba4444',\n          oneBitAlpha:true\n        });\n        const indexed = applyPalette(image.data, palette, 'rgba4444');\n        let transparentIndex = -1;\n        for(let i=0;i<palette.length;i+=1){\n          if(palette[i].length>3 && palette[i][3]===0){\n            transparentIndex=i;\n            break;\n          }\n        }\n        gif.writeFrame(indexed,W,H,{\n          palette,\n          delay:frameDelay,\n          repeat:0,\n          transparent:transparentIndex>=0,\n          transparentIndex:transparentIndex>=0?transparentIndex:0\n        });\n\n        const label = `Export GIF ${frameIndex+1}/${totalFrames}`;\n        if(btnExportGIFTop) btnExportGIFTop.textContent = label;\n        if(btnExportGIF) btnExportGIF.textContent = label;\n        if(recTime) recTime.textContent = `${frameIndex+1} / ${totalFrames}`;\n\n        // Give the UI a chance to repaint during long GIF exports.\n        if(frameIndex % 2 === 1) await new Promise(resolve=>setTimeout(resolve,0));\n      }\n\n      gif.finish();\n      const blob = new Blob([gif.bytes()], {type:'image/gif'});\n      const url = URL.createObjectURL(blob);\n      downloadLink.href = url;\n      downloadLink.download = 'luke-animate.gif';\n      downloadLink.textContent = `Download luke-animate.gif (${(blob.size/1024/1024).toFixed(2)} MB)`;\n      downloadLink.classList.add('show');\n      try{ downloadLink.click(); }catch(error){}\n      setTimeout(()=>URL.revokeObjectURL(url),60000);\n    }catch(error){\n      console.error('Luke Animate GIF export failed:',error);\n      alert('GIF export failed: ' + (error && error.message ? error.message : error));\n    }finally{\n      exportPlayback.active = restoreExportState.active;\n      exportPlayback.fps = restoreExportState.fps;\n      exportPlayback.duration = restoreExportState.duration;\n      exportPlayback.totalFrames = restoreExportState.totalFrames;\n      exportPlayback.currentFrameIndex = restoreExportState.currentFrameIndex;\n      exportPlayback.recorderStarted = restoreExportState.recorderStarted;\n      playing = restorePlaying;\n      t = restoreTime;\n      syncActiveSceneFrameForTime(t, true);\n      if(cleanViewStarted) restoreCleanWebMExportView();\n      gifExportActive = false;\n      if(btnExportGIF){ btnExportGIF.disabled = false; btnExportGIF.textContent = 'Export GIF'; }\n      if(btnExportGIFTop){ btnExportGIFTop.disabled = false; btnExportGIFTop.textContent = 'Export GIF'; }\n      if(btnRecord) btnRecord.disabled = false;\n      if(btnExportWebMTop){ btnExportWebMTop.disabled = false; btnExportWebMTop.textContent = 'Export WebM'; }\n      if(btnStop) btnStop.disabled = true;\n      if(recTime) recTime.textContent = '';\n    }\n  }\n\n  if(btnExportGIFTop){\n    btnExportGIFTop.addEventListener('click', exportAnimatedGIF);\n  }\n  if(btnExportGIF){\n    btnExportGIF.addEventListener('click', exportAnimatedGIF);\n  }\n\n  btnRecord.addEventListener('click', ()=>{'''

if 'async function exportAnimatedGIF()' not in text:
    if anchor not in text:
        raise SystemExit('WebM export event anchor not found')
    text = text.replace(anchor, insert, 1)

path.write_text(text, encoding='utf-8')
print('Luke Animate GIF export patch applied.')
